import numpy as np, random, ot

def greedy_assign(M):
    n=M.shape[0]
    assigned_cols=np.full(n, False)
    rows_ind=[]
    cols_ind=[]
    for i in range(n):
        # sort row indices by value gradually maybe.
        col=np.argmin(np.where(assigned_cols, np.inf, M[i]))
        if not assigned_cols[col]:
            rows_ind.append(i)
            cols_ind.append(col)
            assigned_cols[col]=True
        else:
            # Shouldn't happen; but we circumvent by scanning sorted order.
            order=np.argsort(M[i])
            for col in order:
                if not assigned_cols[col]:
                    rows_ind.append(i); cols_ind.append(col); assigned_cols[col]=True; break
    return np.array(rows_ind), np.array(cols_ind)

def validate(trials=100, n=600):
    for seed in random.sample(range(1_000_000), trials):
        np.random.seed(seed)
        a=ot.utils.unif(n)
        s=np.random.rand(n,2); t=np.random.rand(n,2)
        M=ot.dist(s,t)
        r,c=greedy_assign(M)
        G=np.zeros_like(M)
        G[r,c]=a[r]
        G_ref=ot.lp.emd(a,a,M,check_marginals=False)
        if not np.allclose(G_ref, G):
            return False
    return True
print('validate', validate(50))
